from pathlib import Path
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime,timezone
import json,subprocess,time,urllib.request

AUDIT=Path(__file__).resolve().parent
APP=Path('/home/rana/Projects/System Project/System_Development_Project/distributed-dl-system')
nodes=json.loads((APP/'config/nodes.json').read_text())['nodes']
remote=(AUDIT/'remote_readiness.py').read_text()

def probe(node):
 result={'node':node['id'],'inventory_address':node['ip'],'started_at_utc':datetime.now(timezone.utc).isoformat(),'ssh':{},'http':{}}
 command=['ssh','-T','-o','BatchMode=yes','-o','ConnectTimeout=5','-o','ConnectionAttempts=1','-o','StrictHostKeyChecking=yes','-o','UpdateHostKeys=no','-o','ControlMaster=no','-o','ControlPath=none','-o','ControlPersist=no','-o','ServerAliveInterval=5','-o','ServerAliveCountMax=1',node['id'],'python3 -I -B - '+node.get('worker_root','distributed-dl-system')]
 result['ssh']['command']=command
 try:
  start=time.time();p=subprocess.run(command,input=remote,capture_output=True,text=True,timeout=35)
  result['ssh'].update(returncode=p.returncode,stderr=p.stderr[:4096],elapsed_seconds=round(time.time()-start,3))
  if p.returncode==0:
   try:result['ssh']['data']=json.loads(p.stdout)
   except ValueError:result['ssh']['invalid_json_output']=p.stdout[:4096]
 except (OSError,subprocess.TimeoutExpired) as error:result['ssh']['error']=str(error)
 opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
 for route in ['health','resources']:
  url=f"http://{node['ip']}:{node['port']}/{route}"
  try:
   with opener.open(url,timeout=3) as response:
    data=json.loads(response.read(131072))
    fields=['node','status','architecture','python','execution_ownership'] if route=='health' else ['node','node_state','timestamp','slots','cpu','memory','disk','network','execution_ownership']
    result['http'][route]={'url':url,'status':response.status,'data':{k:data.get(k) for k in fields},'identity_matches':data.get('node')==node['id']}
  except (OSError,ValueError) as error:result['http'][route]={'url':url,'error':str(error)}
 return result

with ThreadPoolExecutor(max_workers=3) as executor:results=list(executor.map(probe,nodes))
(AUDIT/'cluster-readiness.json').write_text(json.dumps(results,indent=2)+'\n')
for result in results:
 ssh=result['ssh'];data=ssh.get('data')
 print(json.dumps({'node':result['node'],'ssh_returncode':ssh.get('returncode'),'ssh_error':ssh.get('error') or ssh.get('stderr'),'hostname':data.get('hostname') if data else None,'architecture':data.get('architecture') if data else None,'http':{route:entry.get('status',entry.get('error')) for route,entry in result['http'].items()}}),flush=True)

