r['exports_files']={}
for path in [Path('/etc/exports'),*Path('/etc/exports.d').glob('*.exports')]:
 try:r['exports_files'][str(path)]={'lines':[line for line in path.read_text().splitlines() if line.strip() and not line.lstrip().startswith('#')]}
 except OSError as error:r['exports_files'][str(path)]={'error':str(error)}
r['active_exports']=command(['exportfs','-v']) if r['tools']['exportfs'] else {'error':'exportfs not installed or not on PATH'}
