   r['fstab_nfs_entries'].append({'source':fields[0],'target':fields[1],'fstype':fields[2],'options':[o for o in fields[3].split(',') if o.split('=',1)[0] in {'ro','rw','nosuid','nodev','noexec','vers','nfsvers','sec','proto','hard','soft','sync','async','_netdev','nofail'}]})
except OSError as error:r['fstab_error']=str(error)
(AUDIT/'controller-readiness.json').write_text(json.dumps(r,indent=2)+'\n')
summary={'tools':r['tools'],'packages':{name:r[name] for name in ['nfs_server_package','nfs_client_package']},'exports_files':r['exports_files'],'nfs_service':r['nfs_service'],'controller_services':r['controller_services'],'path_summary':{name:{k:v for k,v in item.items() if k!='mount'} for name,item in r['paths'].items()}}
