import hashlib,json,os,platform,pwd,grp,shutil,subprocess,sys,time
from pathlib import Path
from importlib import metadata

def read(path,limit=262144):
 try:
  with Path(path).open() as stream:return stream.read(limit)
 except OSError as error:return {'error':str(error)}

def command(args):
 try:
  result=subprocess.run(args,capture_output=True,text=True,timeout=4)
  return {'returncode':result.returncode,'stdout':result.stdout[:65536],'stderr':result.stderr[:4096]}
 except (OSError,subprocess.TimeoutExpired) as error:return {'error':str(error)}

root=Path(sys.argv[1]);root=root if root.is_absolute() else Path.home()/root
report={'hostname':platform.node(),'architecture':platform.machine(),'kernel':platform.release(),'python_base':platform.python_version(),'timestamp':time.time(),'uid':os.getuid(),'gid':os.getgid(),'user':pwd.getpwuid(os.getuid()).pw_name,'worker_root_assumed_from_inventory':str(root),'paths':{},'source_hashes':{}}
for relative in ['.','worker-storage','worker-storage/inputs','worker-storage/environments','worker-storage/jobs','worker-storage/leases','checkpoints','logs']:
 p=root/relative
 try:
  info=p.lstat();v=os.statvfs(p)
  report['paths'][relative]={'uid':info.st_uid,'gid':info.st_gid,'mode':oct(info.st_mode & 0o7777),'symlink':p.is_symlink(),'free_bytes':v.f_bavail*v.f_frsize,'free_inodes':v.f_favail,'device':info.st_dev}
 except OSError as error:report['paths'][relative]={'error':str(error)}
for relative in ['agent/agent.py','agent/environment_worker.py','agent/custom_runner.py','agent/dl_checkpoint.py','agent/checkpoint_protocol.py','agent/execution_lease.py','agent/lease_runner.py','config/execution_leases.json']:
 p=root/relative
 try:report['source_hashes'][relative]=hashlib.sha256(p.read_bytes()).hexdigest()
 except OSError as error:report['source_hashes'][relative]={'error':str(error)}
report['venv_config']=read(root/'.venv/pyvenv.cfg')
sites=list((root/'.venv/lib').glob('python*/site-packages')) if (root/'.venv/lib').is_dir() else []
wanted={'torch','torchvision','numpy','flask','requests','psutil','waitress'}
report['venv_package_metadata']={}
for site in sites:
 try:
  for dist in metadata.distributions(path=[str(site)]):
   name=dist.metadata.get('Name','').lower().replace('_','-')
   if name in wanted:report['venv_package_metadata'][name]=dist.version
 except (OSError,ValueError) as error:report['venv_package_metadata_error']=str(error)
report['network_addresses']=command(['ip','-j','address','show'])
report['link_speeds_mbps']={}
for p in Path('/sys/class/net').glob('*/speed'):
 report['link_speeds_mbps'][p.parent.name]=read(p,128)
report['nfs_mounts']=command(['findmnt','-J','-t','nfs,nfs4','-o','SOURCE,TARGET,FSTYPE,OPTIONS'])
report['cache_filesystem']=command(['findmnt','-J','-T',str(root/'worker-storage'),'-o','SOURCE,TARGET,FSTYPE,OPTIONS'])
report['nfs_client_tools']={name:shutil.which(name) for name in ['mount.nfs','nfsstat','rpcinfo','findmnt']}
filesystems=read('/proc/filesystems')
report['kernel_nfs_filesystems']=[line.strip() for line in filesystems.splitlines() if 'nfs' in line] if isinstance(filesystems,str) else filesystems
report['nfs_client_package']=command(['dpkg-query','-W','-f=${Package} ${Status} ${Version}\n','nfs-common'])
properties=['ActiveState','SubState','User','Group','WorkingDirectory','MainPID','FragmentPath','PrivateMounts','ProtectSystem','ProtectHome','NoNewPrivileges','ReadOnlyPaths','InaccessiblePaths']
report['agent_service']=command(['systemctl','show','dl-node-agent.service','--no-pager',*['--property='+name for name in properties]])
try:
 report['probe_mount_namespace']=os.readlink('/proc/self/ns/mnt')
 service=report['agent_service'].get('stdout','')
 pid=next((line.split('=',1)[1] for line in service.splitlines() if line.startswith('MainPID=')),'0')
 if pid.isdigit() and int(pid)>0:report['agent_mount_namespace']=os.readlink('/proc/'+pid+'/ns/mnt')
except OSError as error:report['namespace_error']=str(error)
print(json.dumps(report,sort_keys=True))
